<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Bezpieczeństwo konta'; ?>
<div class="page-head"><div><p class="eyebrow">Profil</p><h1>Bezpieczeństwo konta</h1></div></div>
<?php if($error):?><div class="alert danger"><?=Html::e($error)?></div><?php endif;?><?php if($notice):?><div class="alert success"><?=Html::e($notice)?></div><?php endif;?>
<section class="card section-card"><h2>Uwierzytelnianie dwuskładnikowe TOTP</h2><?php if($totpEnabled):?><div class="alert success">2FA jest aktywne. Pozostałe kody odzyskiwania: <?=Html::e($remainingRecovery)?></div><form method="post" action="<?=Html::e(Url::to('/profile/security/2fa/disable'))?>" class="stack-form"><?=Csrf::field()?><label>Aktualne hasło<input type="password" name="password" autocomplete="current-password" required></label><button class="button secondary">Wyłącz 2FA</button></form><?php elseif($pendingSecret):?><p>Dodaj konto w aplikacji obsługującej TOTP. Sekret i URI są wyświetlane tylko w trakcie konfiguracji.</p><dl class="system-list"><dt>Sekret</dt><dd><code><?=Html::e($pendingSecret)?></code></dd><dt>URI konfiguracji</dt><dd><code class="break-all"><?=Html::e($provisioningUri)?></code></dd></dl><form method="post" action="<?=Html::e(Url::to('/profile/security/2fa/confirm'))?>" class="stack-form"><?=Csrf::field()?><label>Kod 6-cyfrowy<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required></label><button class="button">Potwierdź i aktywuj</button></form><?php else:?><p>Po aktywacji logowanie wymaga hasła oraz 6-cyfrowego kodu z aplikacji uwierzytelniającej.</p><form method="post" action="<?=Html::e(Url::to('/profile/security/2fa/begin'))?>"><?=Csrf::field()?><button class="button">Skonfiguruj 2FA</button></form><?php endif;?></section>
<?php if(is_array($recoveryCodes)&&$recoveryCodes):?><section class="card section-card"><h2>Kody odzyskiwania</h2><div class="alert warning">Te kody są jednorazowe i nie zostaną pokazane ponownie. Przechowuj je poza imWiki.</div><div class="recovery-grid"><?php foreach($recoveryCodes as $code):?><code><?=Html::e($code)?></code><?php endforeach;?></div></section><?php endif;?>
